	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

var (
	actionRequestMu sync.Mutex
	actionRequests  = make(map[string]bool)
)

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		hashInput := buildHashInput(ids)
		hash := sha256.Sum256([]byte(hashInput))
		requestHash := hex.EncodeToString(hash[:])

		response := protocol.Result{ApprovedIDs: ids}
		responseBytes, _ := json.Marshal(response)

		var existingAction *struct {
			ActorID      string
			RequestHash  string
			ResponseJSON string
		}

		err = tx.QueryRow(ctx,
			`SELECT "actorId", "requestHash", response::text FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
			u.Tenant, u.User, "bulk-approve.v3", key).Scan(&existingAction.ActorID, &existingAction.RequestHash, &existingAction.ResponseJSON)

		if err == pgx.ErrNoRows {
			err = nil
			existingAction = nil
		} else if err != nil {
			return protocol.Result{}, false, err
		}

		if existingAction != nil {
			if existingAction.RequestHash != requestHash || existingAction.ResponseJSON != string(responseBytes) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}

			var auditCount int
			err = tx.QueryRow(ctx, `SELECT COUNT(*) FROM "ApprovalAudit" WHERE "tenantId"=$1 AND "purchaseId"=ANY($2::text[])`, u.Tenant, ids).Scan(&auditCount)
			if err != nil {
				return protocol.Result{}, false, err
			}
			if auditCount == len(ids) {
				return response, true, nil
			}
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		for _, id := range ids {
			_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" ("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus") VALUES ($1, $2, $3, $4, $5, 'submitted', 'approved')`,
				u.Tenant, id, u.User, "bulk-approve.v3", key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		_, err = tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		_, err = tx.Exec(ctx, `INSERT INTO "ActionRequest" ("tenantId", "actorId", operation, key, "requestHash", response) VALUES ($1, $2, $3, $4, $5, $6)`,
			u.Tenant, u.User, "bulk-approve.v3", key, requestHash, responseBytes)
		if err != nil {
			return protocol.Result{}, false, err
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return response, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

func buildHashInput(ids []string) string {
	var buf bytes.Buffer
	buf.WriteString("bulk-approve.v3\n")

	sorted := make([]string, len(ids))
	copy(sorted, ids)
	sort.Strings(sorted)

	for _, id := range sorted {
		buf.WriteString(fmt.Sprintf("%d:%s", len(id), id))
	}
	return buf.String()
}

