		}

		if existingKeys != nil && len(existingKeys) > 0 {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		for _, id := range ids {
			_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" ("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus") VALUES ($1, $2, $3, $4, $5, 'submitted', 'approved')`,
				u.Tenant, id, u.User, "bulk-approve.v3", key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		_, err = tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		_, err = tx.Exec(ctx, `INSERT INTO "ActionRequest" ("tenantId", "actorId", operation, key, "requestHash", response) VALUES ($1, $2, $3, $4, $5, $6)`,
			u.Tenant, u.User, "bulk-approve.v3", key, requestHash, responseBytes)
		if err != nil {
			return protocol.Result{}, false, err
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return response, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}
